import { normalizeRanges } from './normalize-ranges.mjs';

export function subtractRanges(base, removed) {
  if (!Array.isArray(base)) {
    throw new TypeError('base must be an array');
  }
  if (!Array.isArray(removed)) {
    throw new TypeError('removed must be an array');
  }

  let result = normalizeRanges(base);
  const cuts = normalizeRanges(removed);

  for (const [rs, re] of cuts) {
    const next = [];
    for (const [bs, be] of result) {
      if (re <= bs || rs >= be) {
        next.push([bs, be]);
        continue;
      }
      if (bs < rs) {
        next.push([bs, rs]);
      }
      if (re < be) {
        next.push([re, be]);
      }
    }
    result = next;
  }

  return result.map(([start, end]) => [start, end]);
}

